from pathlib import Path
import json,hashlib,statistics
R=Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();rows=[];pins={};docs={}
for arm in ['off','on']:
 p=R/'capture'/arm/'COMPLETED.json';pins[str(p)]=sha(p);d=json.load(open(p));assert d['status']=='ALL10_FLOOR_WORLD_CAPTURE_COMPLETE';docs[arm]=d
 for f in d['frames']:
  m=json.load(open(R/'capture'/arm/(f['prefix']+'.json')));ww=f['floorWorld'];assert f['transportDeltaExactlyNewWorld'];rows.append({'arm':arm,'view':f['view'],'case':f['case'],'renderSeconds':m['hostRenderNsFirstFrame']/1e9,'processSeconds':f['elapsedNs']/1e9,'transportRays':m['transportRays'],'transportNodeVisits':m['transportNodeVisits'],'transportTriangleTests':m['transportTriangleTests'],'worldRays':ww['visibilityRays'],'worldNodeVisits':ww['visibilityNodeVisits'],'worldTriangleTests':ww['visibilityTriangleTests'],'worldMisses':ww['misses'],'worldBlockedFloor':ww['blockedFloor'],'worldBlockedCharacter':ww['blockedCharacter'],'worldEvaluations':ww['evaluations'],'worldWorkUsed':ww['workUsed'],'worldWorkLimit':ww['workLimit'],'semanticReservations':{'shaderSetupMerge':64*ww['shaderCalls'],'directionKernels':4096*ww['evaluations'],'queryControl':2048*ww['evaluations'],'reductionAccumulation':128*ww['evaluations']},'oldCounterSemanticsExact':f['oldCounterSemanticsExact']})
assert len(rows)==20
byarm={a:{'renderSecondsSum':sum(r['renderSeconds'] for r in rows if r['arm']==a),'renderSecondsMedian':statistics.median(r['renderSeconds'] for r in rows if r['arm']==a)} for a in ['off','on']}
maxima={k:max(r[k] for r in rows if r['arm']=='on') for k in ['transportRays','transportNodeVisits','transportTriangleTests','worldRays','worldNodeVisits','worldTriangleTests','worldWorkUsed']};limits={'transportRays':20000000,'transportNodeVisits':800000000,'transportTriangleTests':300000000};assert all(maxima[k]<=v for k,v in limits.items())
summary={'status':'ALL20_CAPTURES_WITHIN_UNCHANGED_VISIBILITY_CAPS','rows':rows,'timingsByArm':byarm,'maximaON':maxima,'unchangedLimits':limits,'maximumUtilization':{k:maxima[k]/v for k,v in limits.items()},'hostTimingCaveat':'single sequential frame processes with observers, not isolated/device timing; scheduling and overlapping work may vary','newStorage':json.load(open(R/'STACK_RESOURCES.json'))['newPersistentHostAdditions'],'old8MCombinedAdmission':False,'firmwareFitClaim':False,'inputPins':pins}
(R/'RESOURCE_SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps({'maximaON':maxima,'timingsByArm':byarm},indent=2))
